import { emit, subscribe, subscriberCount } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import * as activityRepo from "@/server/repositories/activity-repository";
import {
  exportActivity,
  groupByDay,
  listActivity,
  registerActivityListeners,
} from "@/server/services/activity-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { ActivityEvent } from "@/types/activity";
import type { CommentId, IssueId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;
let detach: Unsubscribe;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("activity", "growth");
  detach = registerActivityListeners();
});

afterAll(() => {
  detach();
  cleanup();
});

afterEach(() => {
  vi.mocked(activityRepo.insertActivity).mockClear();
});

describe("services/activity-service", () => {
  // subscribe() is registered for each ActivityAction-shaped event type.
  it("subscribes to every event that maps to an ActivityAction", () => {
    const before = subscriberCount("project.created");
    const off = registerActivityListeners();

    // registerActivityListeners() is idempotent per call — each call attaches
    // its own listener set, so calling it a second time adds one more.
    expect(subscriberCount("project.created")).toBe(before + 1);
    expect(subscriberCount("issue.created")).toBeGreaterThanOrEqual(1);
    expect(subscriberCount("member.role_changed")).toBeGreaterThanOrEqual(1);
    expect(subscriberCount("billing.plan_changed")).toBeGreaterThanOrEqual(1);

    off();
    expect(subscriberCount("project.created")).toBe(before);
  });

  // One emit produces exactly one activity row, with the actor and subject.
  it("records one audit row per emitted event", async () => {

describe("services/issue-service", () => {
  it("refuses issue creation to an actor without issue:create", async () => {
    await expect(
      issueService.createIssue(
        tenant.actors.viewer,
        issueInput(tenant.org.id, tenant.project.id, { title: "Viewer can't do this" }),
      ),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  it("refuses creation when the project is at its plan issue quota", async () => {
    const quotaTenant = await createTenant("issuequota", "free");

    // The free plan allows 100 issues per project; seed that many directly
    // through the repository so the service boundary is the only thing under
    // test here.
    for (let number = 1; number <= 100; number += 1) {
      await issueRepo.insertIssue(
        issueInput(quotaTenant.org.id, quotaTenant.project.id, {
          title: `Seed issue ${number}`,
        }),
        quotaTenant.actors.member.userId,
        number,
      );
    }

    await expect(
      issueService.createIssue(
        quotaTenant.actors.member,
        issueInput(quotaTenant.org.id, quotaTenant.project.id, {
          title: "One too many",
        }),
      ),
    ).rejects.toThrow(/allows no more issues/);
  });

/**
 * Test double for `@/lib/id` (owner E).
 *
 * The server suite needs ids that are valid ULIDs *and* reproducible, so a
 * failing assertion names the same row on every run. Counter-based rather than
 * random for exactly that reason.
 */
const ULID_ALPHABET = "0123456789ABCDEFGHJKMNPQRSTVWXYZ";
const ULID_LENGTH = 26;

let counter = 0;

export function newId(): string {
  counter += 1;
  return encode(counter);
}

export function isUlid(value: string): boolean {
  return (
    value.length === ULID_LENGTH &&
    [...value].every((char) => ULID_ALPHABET.includes(char.toUpperCase()))
  );
}

export function idFactory(seed: number): () => string {
  let local = seed;
  return () => {
    local += 1;
    return encode(local);
  };
}

/** Test-only: rewinds the counter so each file starts from the same ids. */
export function resetIds(): void {
  counter = 0;
}

function encode(value: number): string {
  let remaining = value;
  let out = "";

  while (out.length < ULID_LENGTH) {
    out = `${ULID_ALPHABET[remaining % 32] ?? "0"}${out}`;
    remaining = Math.floor(remaining / 32);
  }

  return out.slice(-ULID_LENGTH);
}

