import { sqliteTable, text, uniqueIndex } from "drizzle-orm/sqlite-core";
import { idColumn, tenantColumns, timestampColumns } from "./_shared";

/**
 * One row per completed bulk import. The key is unique per organization so a
 * re-upload of the same file replays the recorded issues instead of repeating.
 */
export const issueImports = sqliteTable(
  "issue_imports",
  {
    id: idColumn(),
    ...tenantColumns,
    importKey: text("import_key").notNull(),
    projectId: text("project_id").notNull(),
    authorId: text("author_id").notNull(),
    /** JSON array of issue ids, in file order. */
    issueIds: text("issue_ids").notNull().default("[]"),
