cat > src/server/repositories/issue-import-repository.ts <<'EOF'
/**
 * Bulk issue imports: the recorded import keys and the single transaction that
 * writes a whole batch — missing labels, the issues, their label links and the
 * import record — so a failure part-way through leaves nothing behind.
 */
import { and, eq } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, issueImports, issueLabels, issues, labels } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { brandId, parseJsonArray, toIssue } from "./_mappers";
import type {
  IsoTimestamp,
  IssueId,
  LabelId,
  OrgId,
  ProjectId,
  UserId,
} from "@/types/common";
import type { Issue, IssuePriority, IssueStatus } from "@/types/issue";

/** Colour a label gets when an import has to create it. */
const DEFAULT_LABEL_COLOR = "#94a3b8";

export interface IssueImportRecord {
  readonly importKey: string;
  readonly projectId: ProjectId;
  readonly issueIds: readonly IssueId[];
}

/** One issue to write, already resolved against the org's members. */
export interface ImportedIssueDraft {
  readonly title: string;
  readonly description: string | null;
  readonly status: IssueStatus;
  readonly priority: IssuePriority;
  readonly assigneeId: UserId | null;
  readonly dueAt: IsoTimestamp | null;
  /** Label names, de-duplicated, matched case-sensitively. */
  readonly labelNames: readonly string[];
}

export async function findImport(
  orgId: OrgId,
  importKey: string,
): Promise<IssueImportRecord | null> {
  const row = getDb()
    .select()
    .from(issueImports)
    .where(
      and(
        orgPredicate(issueImports.orgId, orgId),
        eq(issueImports.importKey, importKey),
      ),
    )
    .get();
  if (!row) return null;

  return {
    importKey: row.importKey,
    projectId: brandId<ProjectId>(row.projectId),
    issueIds: parseJsonArray<IssueId>(row.issueIds),
  };
}

/**
 * Writes the batch atomically. Issues are numbered from `firstNumber` in the
 * order given; label names the org does not have yet are created once each.
 */
export async function insertImport(
  orgId: OrgId,
  projectId: ProjectId,
  importKey: string,
  authorId: UserId,
  firstNumber: number,
  drafts: readonly ImportedIssueDraft[],
): Promise<readonly Issue[]> {
  const stamp = toIsoTimestamp(new Date());

  return getDb().transaction((tx) => {
    const labelIdByName = new Map<string, LabelId>(
      tx
        .select({ id: labels.id, name: labels.name })
        .from(labels)
        .where(orgPredicate(labels.orgId, orgId))
        .all()
        .map((row) => [row.name, brandId<LabelId>(row.id)]),
    );

    for (const name of drafts.flatMap((draft) => draft.labelNames)) {
      if (labelIdByName.has(name)) continue;
      const id = brandId<LabelId>(newId());
      tx.insert(labels)
        .values({
          id,
          orgId,
          name,
          color: DEFAULT_LABEL_COLOR,
          description: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .run();
      labelIdByName.set(name, id);
    }

    const created = drafts.map((draft, index) => {
      const row = tx
        .insert(issues)
        .values({
          id: newId(),
          orgId,
          projectId,
          number: firstNumber + index,
          title: draft.title,
          description: draft.description,
          status: draft.status,
          priority: draft.priority,
          authorId,
          assigneeId: draft.assigneeId,
          parentId: null,
          estimate: null,
          dueAt: draft.dueAt,
          startedAt: null,
          completedAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .returning()
        .get();

      const labelIds = draft.labelNames.map(
        (name) => labelIdByName.get(name) as LabelId,
      );
      if (labelIds.length > 0) {
        tx.insert(issueLabels)
          .values(
            labelIds.map((labelId) => ({ orgId, issueId: row.id, labelId })),
          )
          .run();
      }

      return toIssue(row, labelIds);
    });

    tx.insert(issueImports)
      .values({
        id: newId(),
        orgId,
        importKey,
        projectId,
        authorId,
        issueIds: JSON.stringify(created.map((issue) => issue.id)),
        createdAt: stamp,
        updatedAt: stamp,
      })
      .run();

    return created;
  });
}
EOF
