import { afterAll, beforeAll, expect, it } from "vitest";
import { getDb } from "@/server/db";
import { registerEventHandlers, unregisterEventHandlers } from "@/server/services/event-registry";
import * as issueService from "@/server/services/issue-service";
import * as usageService from "@/server/services/usage-service";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as activityRepo from "@/server/repositories/activity-repository";
import { NotFoundError } from "@/server/services/_support";
import { TenantScopeError } from "@/lib/tenant";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); registerEventHandlers(); });
afterAll(() => { unregisterEventHandlers(); cleanup(); });

it("imports", async () => {
  const t = await createTenant("imp");
  const other = await createTenant("imp2");
  await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id));
  await usageService.recomputeUsage(t.org.id);
  const res = await issueService.importIssues(t.actors.member, {
    orgId: t.org.id, projectId: t.project.id, importKey: "key-00001",
    rows: [
      { title: "First zebra", description: "d", status: "todo", priority: "high", assigneeEmail: "ADMIN@imp.test", labels: ["Bug", "Bug", "ui"], dueAt: "2026-10-01T00:00:00.000Z" },
      { title: "Second", description: null, status: "backlog", priority: "none", assigneeEmail: "owner@imp2.test", labels: ["ui"], dueAt: null },
    ],
  });
  expect(res.replayed).toBe(false);
  expect(res.issues.map((i) => i.number)).toEqual([2, 3]);
  expect(res.issues[0]?.assigneeId).toBe(t.userIds.admin);
  expect(res.issues[1]?.assigneeId).toBeNull();
  expect(res.issues[0]?.labelIds).toHaveLength(2);
  const usage = await usageRepo.getUsage(t.org.id);
  const recount = await usageRepo.recomputeUsage(t.org.id);
  expect(usage.issuesUsed).toBe(recount.issuesUsed);
  expect(recount.issuesUsed).toBe(3);
  const hits = await searchRepo.searchDocuments({ orgId: t.org.id, q: "zebra", limit: 10, cursor: null } as never);
  expect(hits.items).toHaveLength(1);
  const acts = await activityRepo.listActivity({ orgId: t.org.id, limit: 50, cursor: null } as never);
  console.log(acts.items.map((a) => [a.action, a.subjectKind, JSON.stringify(a.metadata)]));
  const replay = await issueService.importIssues(t.actors.member, {
    orgId: t.org.id, projectId: t.project.id, importKey: "key-00001",
    rows: [{ title: "Other", description: null, status: "backlog", priority: "none", assigneeEmail: null, labels: [], dueAt: null }],
  });
  expect(replay.replayed).toBe(true);
  expect(replay.issues.map((i) => i.id)).toEqual(res.issues.map((i) => i.id));
  const next = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id));
